    PADDLE_CONSENT_HTML = `<!-- Replace your button that opens Paddle Checkout with this form (Paddle.js must be loaded and initialized). -->
<form id="checkbox-paddle-checkout">
  <label style="display:flex;gap:8px;align-items:flex-start;font-size:14px;color:#1f2937;">
    <!-- Never add the "checked" attribute: consent must be an affirmative act -->
    <input type="checkbox" name="auto_renew_consent" value="yes" required>
    <span>I agree that my subscription will automatically renew every {interval} at {price} until I cancel.</span>
  </label>
  <button type="submit">Subscribe</button>
</form>
<script>
  document.getElementById('checkbox-paddle-checkout').addEventListener('submit', function (event) {
    event.preventDefault(); // the browser only gets here once the required box is ticked
    var label = this.querySelector('label span').textContent.trim();
    Paddle.Checkout.open({
      items: [{ priceId: 'pri_REPLACE_ME', quantity: 1 }],
      customData: { auto_renew_consent: { at: new Date().toISOString(), label: label } },
    });
  });
</script>`;
